/**
 * The standalone review page shipped inside every `.html` file generated by
 * `buildReviewFile`. Everything here — markup, styles, and behavior — has to
 * be inlined and dependency-free: the file is emailed around and opened
 * offline, so it cannot fetch fonts, scripts, or anything else over the
 * network. See `build-review-file.ts` for how the placeholders below are
 * filled in.
 *
 * Design tokens are copied from `src/app/globals.css` (the warm dark theme /
 * gold accent) rather than imported, for the same self-containment reason.
 * Font families fall back to system stacks that read close to DM Serif
 * Display / Outfit without a network fetch.
 */

export interface ReviewTemplateData {
  /** Random id embedded in the page and used as the localStorage autosave key. */
  docId: string;
  /** Note title — used for <title> and the on-page heading. */
  title: string;
  /** Pre-escaped title, safe to inline into HTML text nodes/attributes. */
  titleHtml: string;
  /** Author's display name, shown in the page intro. Empty string if unset. */
  authorName: string;
  /** Author's email, used to prefill the "Send back" mailto. Empty string if unset. */
  authorEmail: string;
  /** The note rendered to HTML via markdown-it (html:false, so it's pre-sanitized). */
  bodyHtml: string;
  /** Sanitized filename stem (no extension) used to name the downloaded JSON. */
  filenameStem: string;
}

export function renderReviewTemplate(data: ReviewTemplateData): string {
  const { docId, titleHtml, authorName, authorEmail, bodyHtml, filenameStem } = data;
  const authorLine = authorName
    ? `${escapeHtml(authorName)} sent you this draft to review.`
    : "You've been sent this draft to review.";

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Review: ${titleHtml}</title>
<style>
${STYLES}
</style>
</head>
<body>
<div class="review-shell">

  <header class="review-intro">
    <p class="review-intro-eyebrow">Fragment · Review</p>
    <h1 class="review-intro-title">${titleHtml}</h1>
    <p class="review-intro-sub">${authorLine} Select any text below to leave a comment, or add a general note in the sidebar. When you're done, hit "Send back".</p>
  </header>

  <div class="review-layout">
    <main class="review-doc-wrap">
      <article id="doc" class="review-doc">
${bodyHtml}
      </article>
      <p class="review-footer">Written with Fragment · <a href="https://github.com/anurieli/fragment" rel="noopener">github.com/anurieli/fragment</a></p>
    </main>

    <aside class="review-sidebar">
      <div class="review-sidebar-section">
        <label class="review-label" for="reviewer-name">Your name</label>
        <p class="review-hint">Shown to the author alongside your comments. Saved on this device for next time.</p>
        <input id="reviewer-name" class="review-input" type="text" placeholder="Your name" autocomplete="name">
      </div>

      <div class="review-sidebar-section review-edit-toggle-row">
        <label class="review-checkbox-label">
          <input id="edit-toggle" type="checkbox">
          <span>Edit the text directly</span>
        </label>
        <p class="review-hint">Optional — turns the document editable so you can make direct changes instead of (or alongside) comments.</p>
      </div>

      <div class="review-sidebar-section review-comments-section">
        <div class="review-comments-header">
          <span class="review-label">Comments</span>
          <span id="comments-count" class="review-count">0</span>
        </div>
        <p class="review-hint">Highlighted comments are anchored to text in the document. Click one to jump to it.</p>
        <div id="comments-list" class="review-comments-list"></div>
      </div>

      <div class="review-sidebar-section">
        <label class="review-label" for="note-comment-body">Add a general comment</label>
        <p class="review-hint">Not tied to a specific passage — use this for overall feedback.</p>
        <textarea id="note-comment-body" class="review-textarea" rows="3" placeholder="Overall thoughts..."></textarea>
        <button id="add-note-comment" class="review-btn review-btn-secondary" type="button">Add comment</button>
      </div>

      <div class="review-sidebar-section review-send-section">
        <button id="send-back" class="review-btn review-btn-primary" type="button">Send back</button>
        <p id="send-status" class="review-hint review-send-status" role="status"></p>
      </div>
    </aside>
  </div>
</div>

<div id="selection-popup" class="review-selection-popup" hidden>
  <button id="selection-comment-btn" type="button" class="review-btn review-btn-pill">+ Comment</button>
  <div id="selection-comment-form" class="review-selection-form" hidden>
    <textarea id="selection-comment-body" class="review-textarea" rows="2" placeholder="Your comment..." autofocus></textarea>
    <div class="review-selection-form-actions">
      <button id="selection-comment-cancel" type="button" class="review-btn review-btn-ghost">Cancel</button>
      <button id="selection-comment-save" type="button" class="review-btn review-btn-primary review-btn-sm">Add</button>
    </div>
  </div>
</div>

<script>
${SCRIPT.replace("__DOC_ID__", JSON.stringify(docId))
  .replace("__TITLE__", JSON.stringify(data.title))
  .replace("__AUTHOR_NAME__", JSON.stringify(authorName))
  .replace("__AUTHOR_EMAIL__", JSON.stringify(authorEmail))
  .replace("__FILENAME_STEM__", JSON.stringify(filenameStem))}
</script>
</body>
</html>`;
}

export function escapeHtml(str: string): string {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

