/**
 * Vanilla JS, dependency-free, inlined into the generated review page.
 * `__DOC_ID__` / `__TITLE__` / `__AUTHOR_NAME__` / `__AUTHOR_EMAIL__` /
 * `__FILENAME_STEM__` are replaced with JSON-encoded literals by
 * `renderReviewTemplate` above.
 */
const SCRIPT = `(function () {
  "use strict";

  var DOC_ID = __DOC_ID__;
  var TITLE = __TITLE__;
  var AUTHOR_NAME = __AUTHOR_NAME__;
  var AUTHOR_EMAIL = __AUTHOR_EMAIL__;
  var FILENAME_STEM = __FILENAME_STEM__;
  var STORAGE_KEY = "fragment-review:" + DOC_ID;
  var NAME_KEY = "fragment-review:reviewer-name";
  var CONTEXT_LEN = 30;

  var docEl = document.getElementById("doc");
  var nameInput = document.getElementById("reviewer-name");
  var editToggle = document.getElementById("edit-toggle");
  var commentsListEl = document.getElementById("comments-list");
  var commentsCountEl = document.getElementById("comments-count");
  var noteBodyInput = document.getElementById("note-comment-body");
  var addNoteBtn = document.getElementById("add-note-comment");
  var sendBtn = document.getElementById("send-back");
  var sendStatusEl = document.getElementById("send-status");
  var selectionPopup = document.getElementById("selection-popup");
  var selectionCommentBtn = document.getElementById("selection-comment-btn");
  var selectionForm = document.getElementById("selection-comment-form");
  var selectionBody = document.getElementById("selection-comment-body");
  var selectionSave = document.getElementById("selection-comment-save");
  var selectionCancel = document.getElementById("selection-comment-cancel");

  var originalText = docEl.textContent;
  var comments = []; // {id, anchorText, prefix, suffix, body}
  var pendingRange = null;

  function genId() {
    return "c" + Math.random().toString(36).slice(2, 9) + Date.now().toString(36);
  }

  // ---------------------------------------------------------------------
  // Persistence — autosaves on every change, keyed by the doc's id so
  // reopening the same file in the same browser resumes where you left off.
  // ---------------------------------------------------------------------
  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        reviewerName: nameInput.value,
        comments: comments,
        edited: !!editToggle.checked,
      }));
      if (nameInput.value.trim()) {
        localStorage.setItem(NAME_KEY, nameInput.value);
      }
    } catch (e) { /* storage unavailable — best effort, never block the UI */ }
  }

  function restore() {
    var restoredComments = false;
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var data = JSON.parse(raw);
        if (data && typeof data.reviewerName === "string" && data.reviewerName) {
          nameInput.value = data.reviewerName;
        }
        if (data && Array.isArray(data.comments)) {
          comments = data.comments;
          restoredComments = true;
        }
        if (data && data.edited) {
          editToggle.checked = true;
          docEl.setAttribute("contenteditable", "true");
        }
      }
      if (!nameInput.value) {
        var savedName = localStorage.getItem(NAME_KEY);
        if (savedName) nameInput.value = savedName;
      }
    } catch (e) { /* corrupt/unavailable storage — start fresh */ }

    if (restoredComments) {
      comments.forEach(function (c) {
        if (c.anchorText) applyMarkForComment(c);
      });
    }
    renderCommentList();
  }

  // ---------------------------------------------------------------------
  // DOM Range <-> plain-text offset helpers. #doc's rendered textContent is
  // the coordinate space every anchorText/prefix/suffix is computed against.
  // ---------------------------------------------------------------------
  function resolveBoundary(node, offset) {
    if (node.nodeType === Node.TEXT_NODE) return { node: node, offset: offset };
    if (offset >= node.childNodes.length) {
      var last = node.childNodes[node.childNodes.length - 1];
      if (!last) return { node: node, offset: 0 };
      if (last.nodeType === Node.TEXT_NODE) return { node: last, offset: last.textContent.length };
      return resolveBoundary(last, last.childNodes.length);
    }
    var child = node.childNodes[offset];
    if (child.nodeType === Node.TEXT_NODE) return { node: child, offset: 0 };
    return resolveBoundary(child, 0);
  }

  function getTextOffset(root, node, offset) {
    var resolved = resolveBoundary(node, offset);
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
    var total = 0;
    var current;
    while ((current = walker.nextNode())) {
      if (current === resolved.node) return total + resolved.offset;
      total += current.textContent.length;
    }
    return total;
  }

  function findRangeForOffsets(root, start, end) {
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
    var total = 0;
    var current;
    var range = document.createRange();
    var startSet = false, endSet = false;
    while ((current = walker.nextNode())) {
      var len = current.textContent.length;
      if (!startSet && start <= total + len) {
        range.setStart(current, Math.max(0, start - total));
        startSet = true;
      }
      if (!endSet && end <= total + len) {
        range.setEnd(current, Math.max(0, end - total));
        endSet = true;
        break;
      }
      total += len;
    }
    if (!startSet || !endSet) return null;
    return range;
  }

  // ---------------------------------------------------------------------
  // Anchoring — mirrors src/lib/review/anchor-comments.ts. Kept in sync by
  // hand since this file must stay a single dependency-free artifact.
  // ---------------------------------------------------------------------
  function findAllOccurrences(haystack, needle) {
    if (!needle) return [];
    var positions = [];
    var from = 0;
    for (;;) {
      var idx = haystack.indexOf(needle, from);
      if (idx === -1) break;
      positions.push(idx);
      from = idx + 1;
    }
    return positions;
  }

  function locateAnchor(text, anchorText, prefix, suffix) {
    if (!anchorText) return null;
    var positions = findAllOccurrences(text, anchorText);
    if (positions.length === 0) return null;
    if (positions.length === 1) {
      return { start: positions[0], end: positions[0] + anchorText.length };
    }
    var candidates = positions.filter(function (start) {
      var end = start + anchorText.length;
      var before = text.slice(0, start);
      var after = text.slice(end);
      var prefixOk = !prefix || before.slice(-prefix.length) === prefix;
      var suffixOk = !suffix || after.slice(0, suffix.length) === suffix;
      return prefixOk && suffixOk;
    });
    if (candidates.length !== 1) return null;
    return { start: candidates[0], end: candidates[0] + anchorText.length };
  }

  function applyMarkForComment(comment) {
    var text = docEl.textContent;
    var pos = locateAnchor(text, comment.anchorText, comment.prefix, comment.suffix);
    if (!pos) return;
    var range = findRangeForOffsets(docEl, pos.start, pos.end);
    if (!range) return;
    wrapRangeWithMark(range, comment.id);
  }

  function wrapRangeWithMark(range, commentId) {
    var startNode = range.startContainer, startOffset = range.startOffset;
    var endNode = range.endContainer, endOffset = range.endOffset;
    var walker = document.createTreeWalker(docEl, NodeFilter.SHOW_TEXT, null);
    var nodes = [];
    var inRange = false;
    var current;
    while ((current = walker.nextNode())) {
      if (current === startNode) inRange = true;
      if (inRange) nodes.push(current);
      if (current === endNode) break;
    }
    nodes.forEach(function (node) {
      var from = (node === startNode) ? startOffset : 0;
      var to = (node === endNode) ? endOffset : node.textContent.length;
      if (from >= to) return;
      var text = node.textContent;
      var before = text.slice(0, from);
      var middle = text.slice(from, to);
      var after = text.slice(to);
      var mark = document.createElement("mark");
      mark.className = "review-mark";
      mark.setAttribute("data-comment-id", commentId);
      mark.textContent = middle;
      var parent = node.parentNode;
      if (!parent) return;
      var frag = document.createDocumentFragment();
      if (before) frag.appendChild(document.createTextNode(before));
      frag.appendChild(mark);
      if (after) frag.appendChild(document.createTextNode(after));
      parent.replaceChild(frag, node);
    });
  }

  function removeMarksForComment(commentId) {
    var marks = docEl.querySelectorAll('mark.review-mark[data-comment-id="' + commentId + '"]');
    marks.forEach(function (mark) {
      var parent = mark.parentNode;
      if (!parent) return;
      while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
      parent.removeChild(mark);
      parent.normalize();
    });
  }

  function flashComment(commentId) {
    var mark = docEl.querySelector('mark.review-mark[data-comment-id="' + commentId + '"]');
    if (!mark) return;
    mark.scrollIntoView({ behavior: "smooth", block: "center" });
    mark.classList.add("flash");
    setTimeout(function () { mark.classList.remove("flash"); }, 900);
  }

  // ---------------------------------------------------------------------
  // Comment list rendering
  // ---------------------------------------------------------------------
  function renderCommentList() {
    commentsCountEl.textContent = String(comments.length);
    commentsListEl.innerHTML = "";
    if (comments.length === 0) {
      var empty = document.createElement("p");
      empty.className = "review-empty";
      empty.textContent = "No comments yet — select text in the document to add one.";
      commentsListEl.appendChild(empty);
      return;
    }
    comments.forEach(function (c) {
      var card = document.createElement("div");
      card.className = "review-comment-card";

      var excerpt = document.createElement("p");
      excerpt.className = "review-comment-excerpt";
      excerpt.textContent = c.anchorText
        ? ('"' + (c.anchorText.length > 60 ? c.anchorText.slice(0, 60) + "\\u2026" : c.anchorText) + '"')
        : "General comment";
      card.appendChild(excerpt);

      var body = document.createElement("p");
      body.className = "review-comment-body";
      body.textContent = c.body;
      card.appendChild(body);

      var del = document.createElement("button");
      del.type = "button";
      del.className = "review-comment-delete";
      del.setAttribute("aria-label", "Delete comment");
      del.textContent = "\\u00D7";
      del.addEventListener("click", function (e) {
        e.stopPropagation();
        comments = comments.filter(function (x) { return x.id !== c.id; });
        removeMarksForComment(c.id);
        renderCommentList();
        save();
      });
      card.appendChild(del);

      if (c.anchorText) {
        card.addEventListener("click", function () { flashComment(c.id); });
      }

      commentsListEl.appendChild(card);
    });
  }

  // ---------------------------------------------------------------------
  // Selection -> comment flow
  // ---------------------------------------------------------------------
  function hideSelectionPopup() {
    selectionPopup.hidden = true;
    selectionForm.hidden = true;
    selectionBody.value = "";
    pendingRange = null;
  }

  function showSelectionPopup(x, y) {
    selectionForm.hidden = true;
    selectionPopup.hidden = false;
    var popupWidth = 240;
    var left = Math.min(Math.max(8, x - popupWidth / 2), window.innerWidth - popupWidth - 8);
    var top = Math.min(y + 12, window.innerHeight - 60);
    selectionPopup.style.left = left + "px";
    selectionPopup.style.top = top + "px";
  }

  document.addEventListener("mouseup", function (e) {
    if (selectionPopup.contains(e.target)) return;
    var sel = window.getSelection();
    if (!sel || sel.isCollapsed || sel.rangeCount === 0) { hideSelectionPopup(); return; }
    var range = sel.getRangeAt(0);
    if (!docEl.contains(range.commonAncestorContainer)) { hideSelectionPopup(); return; }
    if (range.toString().trim().length === 0) { hideSelectionPopup(); return; }
    pendingRange = range.cloneRange();
    showSelectionPopup(e.clientX, e.clientY);
  });

  document.addEventListener("mousedown", function (e) {
    if (!selectionPopup.contains(e.target) && e.target !== docEl && !docEl.contains(e.target)) {
      hideSelectionPopup();
    }
  });

  selectionCommentBtn.addEventListener("click", function () {
    selectionForm.hidden = false;
    selectionBody.focus();
  });

  selectionCancel.addEventListener("click", hideSelectionPopup);

  selectionSave.addEventListener("click", function () {
    if (!pendingRange) return;
    var body = selectionBody.value.trim();
    if (!body) { selectionBody.focus(); return; }

    var text = docEl.textContent;
    var start = getTextOffset(docEl, pendingRange.startContainer, pendingRange.startOffset);
    var end = getTextOffset(docEl, pendingRange.endContainer, pendingRange.endOffset);
    if (end < start) { var tmp = start; start = end; end = tmp; }
    var anchorText = text.slice(start, end);
    var prefix = text.slice(Math.max(0, start - CONTEXT_LEN), start);
    var suffix = text.slice(end, end + CONTEXT_LEN);

    var comment = { id: genId(), anchorText: anchorText, prefix: prefix, suffix: suffix, body: body };
    comments.push(comment);
    wrapRangeWithMark(pendingRange, comment.id);
    window.getSelection().removeAllRanges();
    hideSelectionPopup();
    renderCommentList();
    save();
  });

  addNoteBtn.addEventListener("click", function () {
    var body = noteBodyInput.value.trim();
    if (!body) { noteBodyInput.focus(); return; }
    comments.push({ id: genId(), anchorText: "", prefix: "", suffix: "", body: body });
    noteBodyInput.value = "";
    renderCommentList();
    save();
  });

  nameInput.addEventListener("input", save);
  nameInput.addEventListener("blur", save);

  editToggle.addEventListener("change", function () {
    docEl.setAttribute("contenteditable", editToggle.checked ? "true" : "false");
    save();
  });

  // ---------------------------------------------------------------------
  // Send back — downloads the .fragment-review.json return payload, then
  // opens a prefilled mailto to the author. mailto can't carry attachments,
  // so the email body says so plainly and asks the reviewer to attach the
  // file that was just downloaded.
  // ---------------------------------------------------------------------
  function sanitizeFilename(name) {
    var out = name.trim().toLowerCase().replace(/\\s+/g, "-").replace(/[^a-z0-9-]/g, "");
    return out || "untitled";
  }

  sendBtn.addEventListener("click", function () {
    var reviewerName = nameInput.value.trim() || "Anonymous reviewer";
    var edited = !!editToggle.checked;
    var currentText = docEl.innerText || docEl.textContent;
    var editedFullText = (edited && currentText.trim() !== originalText.trim()) ? currentText : undefined;

    var payload = {
      docId: DOC_ID,
      reviewerName: reviewerName,
      timestamp: Date.now(),
      comments: comments,
    };
    if (editedFullText !== undefined) payload.editedFullText = editedFullText;

    var filename = (FILENAME_STEM || sanitizeFilename(TITLE)) + ".fragment-review.json";
    var blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);

    var bodyLines = [
      reviewerName + " here — I reviewed \\"" + TITLE + "\\" and left " + comments.length + " comment" + (comments.length === 1 ? "" : "s") + ".",
      "",
      "This browser just downloaded a file called \\"" + filename + "\\" to your Downloads folder.",
      "Email links can't attach files automatically, so please attach it to this email yourself before sending.",
    ];
    var mailBody = bodyLines.join("\\n");
    var mailto = "mailto:" + encodeURIComponent(AUTHOR_EMAIL || "") +
      "?subject=" + encodeURIComponent("Review: " + TITLE) +
      "&body=" + encodeURIComponent(mailBody);

    sendStatusEl.textContent = "Downloaded " + filename + " — attach it to the email that just opened.";

    setTimeout(function () { window.location.href = mailto; }, 300);
  });

  restore();
})();`;
